from taf.sbts.oam.coam.admin.schemas.procedure.lte_ccm_uplink import LTECCMUplink


class LTECCMUplinkNPuschFormat2(LTECCMUplink):
    def __init__(self, lncel_rdn, measurement_type, reporting_time_interval, reception_subframe,
                 exception_subframe, earfcn, nb_subcarrier_index, nb_repetitions, nb_subframe_offset, expection_bundle,
                 reception_bundle, root_seq_index=None, prach_cs=None, prach_hs_flag=None, phys_cell_id=None,
                 tdd_frame_conf=None, tdd_spec_subf_conf=None):
        super(LTECCMUplinkNPuschFormat2, self).__init__(lncel_rdn=lncel_rdn,
                                                        measurement_type=measurement_type,
                                                        reporting_time_interval=reporting_time_interval,
                                                        reception_subframe=reception_subframe,
                                                        exception_subframe=exception_subframe,
                                                        earfcn=earfcn,
                                                        root_seq_index=root_seq_index,
                                                        prach_cs=prach_cs,
                                                        prach_hs_flag=prach_hs_flag,
                                                        phys_cell_id=phys_cell_id,
                                                        tdd_frame_conf=tdd_frame_conf,
                                                        tdd_spec_subf_conf=tdd_spec_subf_conf)

        self.n_pusch_format_2_params = {"nbSubcarrierIndex": self.validate_param('nbSubcarrierIndex',
                                                                                 nb_subcarrier_index,
                                                                                 validity_clause=(
                                                                                     nb_subcarrier_index in [
                                                                                         'NBS_0', 'NBS_1',
                                                                                         'NBS_2', 'NBS_3',
                                                                                         'NBS_4', 'NBS_5',
                                                                                         'NBS_6', 'NBS_7',
                                                                                         'NBS_8', 'NBS_9',
                                                                                         'NBS_10', 'NBS_11'
                                                                                     ]
                                                                                 )),
                                        "nbRepetitions": self.validate_param('nbRepetitions',
                                                                             nb_repetitions,
                                                                             validity_clause=(
                                                                                 nb_repetitions in [
                                                                                     'NBR_1', 'NBR_16', 'NBR_64'
                                                                                 ]
                                                                             )),
                                        "nbSubframeOffset": self.validate_param('nbSubframeOffset',
                                                                                nb_subframe_offset,
                                                                                [0, 255]),
                                        "expectionBundle": self.validate_param('expectionBundle',
                                                                               expection_bundle,
                                                                               [0, 31]),
                                        "receptionBundle": self.validate_param('receptionBundle',
                                                                               reception_bundle,
                                                                               [1, 31])
                                        }

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_n_pusch_format_2_params(parameter):
            return response_dict['params']['nPuschFormat2Params'][parameter]

        lncel_rdn = response_dict['lncel_rDN']
        measurement_type = response_dict['params']['measurementType']
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        reception_subframe = response_dict['params']['receptionSubframe']
        exception_subframe = response_dict['params']['expectionSubframe']
        earfcn = response_dict['params']['earfcn']
        root_seq_index = response_dict['params']['rootSeqIndex'] if 'rootSeqIndex' in response_dict['params'] else None
        prach_cs = response_dict['params']['prachCS'] if 'prachCS' in response_dict['params'] else None
        prach_hs_flag = response_dict['params']['prachHsFlag'] if 'prachHsFlag' in response_dict['params'] else None
        phys_cell_id = response_dict['params']['physCellId'] if 'physCellId' in response_dict['params'] else None
        tdd_frame_conf = response_dict['params']['tddFrameConf'] if 'tddFrameConf' in response_dict['params'] else None
        tdd_spec_subf_conf = response_dict['params']['tddSpecSubfConf'] if 'tddSpecSubfConf' in response_dict[
            'params'] else None

        n_pusch_format_2_params = {
            "nbSubcarrierIndex": _get_n_pusch_format_2_params('nbSubcarrierIndex'),
            "nbRepetitions": _get_n_pusch_format_2_params('nbRepetitions'),
            "nbSubframeOffset": _get_n_pusch_format_2_params('nbSubframeOffset'),
            "expectionBundle": _get_n_pusch_format_2_params('expectionBundle'),
            "receptionBundle": _get_n_pusch_format_2_params('receptionBundle')
        }

        return cls(lncel_rdn=lncel_rdn,
                   measurement_type=measurement_type,
                   reporting_time_interval=reporting_time_interval,
                   reception_subframe=reception_subframe,
                   exception_subframe=exception_subframe,
                   earfcn=earfcn,
                   nb_subcarrier_index=n_pusch_format_2_params['nbSubcarrierIndex'],
                   nb_repetitions=n_pusch_format_2_params['nbRepetitions'],
                   nb_subframe_offset=n_pusch_format_2_params['nbSubframeOffset'],
                   expection_bundle=n_pusch_format_2_params['expectionBundle'],
                   reception_bundle=n_pusch_format_2_params['receptionBundle'],
                   root_seq_index=root_seq_index,
                   prach_cs=prach_cs,
                   prach_hs_flag=prach_hs_flag,
                   phys_cell_id=phys_cell_id,
                   tdd_frame_conf=tdd_frame_conf,
                   tdd_spec_subf_conf=tdd_spec_subf_conf)

    def as_dict(self):
        attributes = super(LTECCMUplinkNPuschFormat2, self).as_dict()
        self.n_pusch_format_2_params = self.filter_empty_parameters(self.n_pusch_format_2_params)
        attributes['params']['nPuschFormat2Params'] = self.n_pusch_format_2_params

        return attributes
